function sortUsers(users, field, direction = 'asc') {
  const sign = direction === 'desc' ? -1 : 1;
  return [...users].sort((a, b) => {
    const x = a[field];
    const y = b[field];
    if (typeof x === 'number' && typeof y === 'number') return (x - y) * sign;
    return String(x).localeCompare(String(y)) * sign;
  });
}
